cat > js/theme.js <<'EOF'
const themeBtn = document.getElementById('theme-btn');
const savedTheme = localStorage.getItem('arctrade-theme');

const updateThemeButton = () => {
  if (!themeBtn) return;
  themeBtn.textContent = document.body.classList.contains('dark') ? '☀️' : '🌙';
};

if (savedTheme === 'dark') {
  document.body.classList.add('dark');
}

updateThemeButton();

if (themeBtn) {
  themeBtn.addEventListener('click', () => {
    document.body.classList.toggle('dark');
    const currentTheme = document.body.classList.contains('dark') ? 'dark' : 'light';
    localStorage.setItem('arctrade-theme', currentTheme);
    updateThemeButton();
  });
}
EOF

cat > js/app.js <<'EOF'
document.addEventListener('DOMContentLoaded', () => {
  const currentPage = window.location.pathname.split('/').pop() || 'index.html';
  const navLinks = document.querySelectorAll('.nav-links a');
  navLinks.forEach(link => {
    if (link.getAttribute('href') === currentPage) {
      link.classList.add('active');
    }
  });

  const contactForm = document.querySelector('.contact-form');
  if (contactForm) {
    contactForm.addEventListener('submit', event => {
      event.preventDefault();
      alert('Thanks! Your message has been sent.');
      contactForm.reset();
    });
  }
});
EOF

cat > js/market.js <<'EOF'
const marketData = [
  { company: 'Reliance', price: '₹2900', change: '+2.5%' },
  { company: 'TCS', price: '₹3850', change: '+1.2%' },
  { company: 'Infosys', price: '₹1700', change: '-0.4%' },
  { company: 'HDFC Bank', price: '₹1640', change: '+0.8%' },
  { company: 'ICICI Bank', price: '₹940', change: '-0.2%' }
];

const marketTableBody = document.getElementById('market-table-body');

if (marketTableBody) {
  marketTableBody.innerHTML = '';
  marketData.forEach(stock => {
    const row = document.createElement('tr');
    row.innerHTML = `
      <td>${stock.company}</td>
      <td>${stock.price}</td>
      <td class="${stock.change.startsWith('-') ? 'down' : 'up'}">${stock.change}</td>
    `;
    marketTableBody.appendChild(row);
  });
}
